-- 06-0-prepare.sql — step 1 of the split 06-apply-rewrites.sql (generated by split_06.py).
-- Creates the private schema audit_backup (if missing) and the EMPTY proposals table
-- audit_backup.rewrites_20261122_proposals with RLS on and no grants. No change to public tables.
-- Safe to run again (IF NOT EXISTS). Run with psql -v ON_ERROR_STOP=1 -f <file>, or paste the whole file into the SQL editor (one call per file).
-- Order: 06-0-prepare → 06-1-load-001 … 06-1-load-007 → 06-2-backup → 06-3-apply. Rollback: 06-4-rollback.

begin;

create schema if not exists audit_backup;
revoke all on schema audit_backup from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on schema audit_backup from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on schema audit_backup from authenticated';
  end if;
end $$;

create table if not exists audit_backup.rewrites_20261122_proposals (
  locale   text   not null,
  slug     text   not null,
  field    text   not null,
  col      text   not null,   -- destinations column (tagline, seo_description, travel_plan) or 'fields'
  path     text[],            -- JSON path inside travel_plan / fields; null for plain columns
  decision text   not null check (decision in ('REWRITE', 'CLEAR')),
  old_text text   not null,
  new_text text   not null,   -- '' for CLEAR
  primary key (locale, slug, field)
);


alter table audit_backup.rewrites_20261122_proposals enable row level security;
revoke all on audit_backup.rewrites_20261122_proposals from public;
do $$
declare r text;
begin
  foreach r in array array['anon', 'authenticated'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke all on audit_backup.rewrites_20261122_proposals from %I', r);
    end if;
  end loop;
end $$;

commit;
